import {plannerDefaults,plannerView,bindPlanner} from './journey-planner.js';
import {performanceCard} from './performance.js';
import {feeDefaults,feeSection,bindFeeImpact} from './fee-impact.js';
import {FUNDS,ACCOUNTS,money,percent,profile,fundCost,totalCost,allowedFund,tfsaCheck,project,matchInvestments} from './core.js';
import {newGoals,newQuestions,homeView,profileView,growthChart,matchCard} from './journey-ui.js';
const app=document.querySelector('#app');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const source=(url,label='Provider details')=>`<a target="_blank" rel="noopener" href="https://www.sygnia.co.za/blog/${url}">${label} ↗</a>`;
const goals=newGoals;
const plannerDrafts={};
let answers={},step=0,account='',fund='',applyStep=0,application={},documents={},completed=false;
let calc={monthly:1000,lump:0,years:20,gross:10,inc:5,afterFees:true,fund:FUNDS[3]};
function go(route){if(location.hash==='#'+route)render();else location.hash=route}
function shell(content){app.innerHTML=`<div class="wrap">${content}</div>`}
function title(k,h,l){return `<div class="page-title"><p class="eyebrow">${k}</p><h1>${h}</h1><p class="lead">${l}</p></div>`}
const feeState={...feeDefaults};
let homeCalc={monthly:1000,lump:0,years:20,gross:10,inc:5,afterFees:true,fund:FUNDS[3]};
function startJourney(){answers.monthly??=String(homeCalc.monthly);answers.lump??='0';answers.horizon??=String(homeCalc.years);step=0;go('profile')}
function home(){shell(homeView(homeCalc).replace('<section class="how-section"',feeSection(feeState)+'<section class="how-section"'));bindFeeImpact(app,feeState);document.querySelector('#start').onclick=startJourney;app.querySelectorAll('[data-start]').forEach(b=>b.onclick=startJourney);document.querySelector('#home-monthly').oninput=updateHomeGraph;document.querySelector('#home-years').oninput=updateHomeGraph}
function updateHomeGraph(){homeCalc.monthly=+document.querySelector('#home-monthly').value;homeCalc.years=+document.querySelector('#home-years').value;const p=project(homeCalc);document.querySelector('#home-monthly-label').textContent=money(homeCalc.monthly);document.querySelector('#home-years-label').textContent=homeCalc.years+' years';document.querySelector('#hero-value').innerHTML='<span class="growth-kicker">'+money(homeCalc.monthly)+' a month could become</span><strong>'+money(p.value)+'</strong><p>over '+homeCalc.years+' years, after modelled fees</p>';document.querySelector('#hero-chart').innerHTML=growthChart(p,{compact:true,id:'hero'});const numbers=app.querySelectorAll('.explain-number');numbers[0].textContent=money(p.paid);numbers[1].textContent=money(Math.max(0,p.value-p.paid));numbers[0].nextElementSibling.textContent='You contribute over '+homeCalc.years+' years'}
const questions=newQuestions;
function field(id,label,type='text',value='',min,max,inputStep=1){return `<label class="field">${label}<input name="${id}" type="${type}" value="${esc(value)}" ${min!==undefined?`min="${min}"`:''} ${max!==undefined?`max="${max}"`:''} ${type==='number'?`step="${inputStep}" inputmode="decimal"`:''} required autocomplete="off"></label>`}
function profilePage(){const q=questions[step];if(q.id==='amounts'){journeyPlannerPage();return}shell(profileView(q,step,answers,field,esc));document.querySelector('#back').onclick=()=>{if(step){step--;profilePage()}else go('home')};document.querySelector('#question-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(q.id==='amounts'&&+d.monthly<=0&&+d.lump<=0){document.querySelector('#form-error').textContent='Choose a monthly or once-off amount to start your plan.';return}Object.assign(answers,d);account='';fund='';completed=false;if(step<questions.length-1){step++;profilePage()}else go('result');window.scrollTo(0,0)}}
function journeyPlannerPage(){
 const p={...(plannerDrafts[answers.goal]||plannerDefaults(answers)),age:Number(answers.age)};
 shell(plannerView(p,questions.length));
 bindPlanner(app,p,growthChart,{back(){step=1;profilePage()},change(d){plannerDrafts[answers.goal]=d},continuePlan(d,r){Object.assign(answers,{monthly:String(d.monthly),lump:String(d.lump),horizon:String(r.years),contributionIncrease:String(d.inc),growthAfterFees:String(d.ret)});account='';fund='';completed=false;application.choice=undefined;step++;profilePage();window.scrollTo(0,0)}});
}
function hasProfile(){return answers.horizon!==undefined&&questions.every(q=>q.f?q.f.every(([id])=>answers[id]!==undefined):answers[q.id]!==undefined)}
function fundCard(f,choose=false){return `<article class="fund-card ${fund===f.id?'chosen':''}"><div class="fund-top"><span class="tag">${f.risk} risk</span><span class="fund-number">${f.equity===null?'Global':f.equity===0?'Cash':f.equity}</span></div><p class="eyebrow">SYGNIA</p><h3>${f.name}</h3><p class="muted">${f.summary}</p><div class="fund-stats"><span><small>Timeframe</small><strong>${f.years?f.years+'+ years':'0–2 years'}</strong></span><span><small>Fund cost / year</small><strong>${percent(fundCost(f))}</strong></span></div>${performanceCard(f)}<details><summary>Benefits, risks & source</summary><div class="detail-body"><p><b>Benefit:</b> ${f.good}</p><p><b>Trade-off:</b> ${f.bad}</p><p>${f.reg28?'Regulation 28 compliant.':'Not Regulation 28 compliant; excluded from RA choices.'}</p><p>${source('fund/'+f.url+'/','Fund details & fact sheet')}</p></div></details><p class="micro">TER ${percent(f.ter)} + transaction costs ${percent(f.tc)}. June 2026. Platform and provider costs are additional.</p>${choose?`<button class="button ${fund===f.id?'':'secondary'}" data-fund="${f.id}">${fund===f.id?'Selected ✓':'Choose this fund'}</button>`:''}</article>`}
function accountCard(a,choose=false){return `<article class="account-card ${account===a.id?'chosen':''}"><div><span class="tag">${a.short}</span><h3>${a.name}</h3><p class="muted">${a.desc}</p></div><div class="proscons"><p><b>What you gain</b>${a.good}</p><p><b>What to keep in mind</b>${a.bad}</p></div><details><summary>Access, rules & provider details</summary><div class="detail-body"><p>${a.access}</p><p>${a.rule}</p><p>${source('product/'+a.url+'/')}</p></div></details>${choose?`<button data-account="${a.id}" class="button ${account===a.id?'':'secondary'}">${account===a.id?'Selected ✓':'Compare with this account'}</button>`:''}</article>`}
function resultPage(){
 if(!hasProfile()){shell(title('YOUR INVESTMENT MATCHES','Let’s build your plan.','A few questions will help us match the account and fund to your goals.')+'<button id="start-matching" class="button">Find my investment →</button>');document.querySelector('#start-matching').onclick=startJourney;return}
 const matched=matchInvestments(answers),p=matched.profile,top=matched.options[0],f=top.fund||FUNDS[p.level];
const tfsaIllustration=top.account.id==='tfsa';const illustrated=project({monthly:+answers.monthly,lump:+answers.lump,years:+answers.horizon,gross:Number(answers.growthAfterFees??10),inc:Number(answers.contributionIncrease??5),afterFees:true,annualLimit:tfsaIllustration?46000:Infinity,fund:f,contributionLimit:tfsaIllustration?500000:Infinity});
 shell('<div class="matched-intro"><div><p class="eyebrow">YOUR PLAN IS TAKING SHAPE</p><h1>Meet your<br><em>investment matches.</em></h1><p class="lead">Your goal. Your risk profile. A fund matched automatically.<br>Choose the account you’d like to start with.</p></div><div class="profile-badge"><span>YOUR RISK PROFILE</span><strong>'+p.label+'</strong><div class="risk-bars">'+Array.from({length:5},(_,i)=>'<span class="'+(i<=p.level?'on':'')+'" style="height:'+(18+i*10)+'px"></span>').join('')+'</div><button class="text-button" id="edit">Edit my answers</button></div></div><div class="summary-pills"><span>'+goals.find(g=>g[0]===answers.goal)?.[1]+'</span><span>'+answers.horizon+' years</span><span>'+money(+answers.monthly)+' a month</span><span>'+money(+answers.lump)+' initial lump sum</span><span>'+Number(answers.contributionIncrease||0)+'% yearly contribution increase</span></div><button id="review-plan" class="text-button">Review my planning calculator ↗</button>'+(p.limited?'<p class="match-context">Your timeframe and ability to stay invested are reflected in the fund match.</p>':'')+p.warnings.map(w=>'<p class="match-context">'+w+'</p>').join('')+'<div class="matches-grid">'+matched.options.slice(0,2).map((m,i)=>matchCard(m,{featured:i===0,years:+answers.horizon})).join('')+'</div>'+(matched.options.length>2?'<details class="extra-matches"><summary>See '+(matched.options.length-2)+' other account option'+(matched.options.length>3?'s':'')+'</summary><div class="matches-grid">'+matched.options.slice(2).map(m=>matchCard(m)).join('')+'</div></details>':'')+'<section class="section growth-result"><div class="section-head"><div><p class="eyebrow">YOUR POTENTIAL OVER TIME</p><h2>A view of what you’re building.</h2></div><div class="result-value"><span>Illustrated value in '+answers.horizon+' years</span><strong>'+money(illustrated.value)+'</strong></div></div>'+growthChart(illustrated,{id:'result'})+'<div class="growth-bottom"><span>You contribute <b>'+money(illustrated.paid)+'</b></span><button class="text-button" id="open-calc">Explore the numbers ↗</button></div><p class="micro">This chart shows your new investment only; existing retirement savings are not included. It uses '+Number(answers.growthAfterFees??10)+'% yearly growth after all fees and a '+Number(answers.contributionIncrease??5)+'% yearly contribution increase. Monthly payments are invested at the start of each month. Fees are included in the assumed growth rate and are not deducted again. Personal and policy taxes are excluded. Not a forecast. Actual returns can be negative.'+(tfsaIllustration?' TFSA illustration assumes no previous contributions and limits contributions to R46,000 a year and stops at R500,000; your remaining allowance may be lower.':'')+'</p></section><details class="method"><summary>How your matches were worked out</summary><div class="detail-body">Your timeframe, experience, reaction to market falls and flexibility create the risk profile. It maps automatically to Money Market, Balanced 40, Balanced 60, Balanced 70 or Worldwide Flexible. RAs use a Regulation 28-compliant fund and stop at Balanced 70. Account order also uses your goal, access preference, tax-rate answer and TFSA status. A short timeframe keeps the fund cautious. Endowment fund eligibility needs separate provider confirmation. This is a demonstration model pending validation before live use.</div></details><p class="micro" style="margin-top:20px">Preview matches based on the information provided. Final eligibility, provider fees and the automated matching model require confirmation before launch.</p>');
 document.querySelector('#review-plan').onclick=()=>{step=2;go('profile')};
 document.querySelector('#edit').onclick=()=>{step=0;go('profile')};
 app.querySelectorAll('[data-match]').forEach(b=>{b.disabled=p.blocked;b.onclick=()=>{const m=matchInvestments(answers).options.find(m=>m.account.id===b.dataset.match);if(!m)return;account=m.account.id;fund=m.fund?.id||'';applyStep=0;application.choice=undefined;go('apply')}});
 document.querySelector('#open-calc').onclick=()=>{calc={monthly:+answers.monthly,lump:+answers.lump,years:+answers.horizon,gross:Number(answers.growthAfterFees??10),inc:Number(answers.contributionIncrease??5),afterFees:true,fund:f};go('calculator')};
}
function accountsPage(){shell(title('THE ACCOUNT COMES FIRST','Know the rules.<br>Then make your choice.','The account sets the tax and access rules. The fund is what your money is invested in.')+`<div class="account-grid">${ACCOUNTS.map(a=>accountCard(a)).join('')}</div><p class="micro" style="margin-top:20px">Tax rules checked on 9 September 2026. <a target="_blank" rel="noopener" href="https://www.sars.gov.za/types-of-tax/personal-income-tax/tax-free-investments/">SARS TFSA rules ↗</a></p>`)}
function fundsPage(){shell(title('THE SYGNIA FUND RANGE','Less to sort through.<br>More to understand.','Compare a focused range, led by the Skeleton Balanced funds. Open a card for benefits, risks and official information.')+`<div class="notice" style="margin-bottom:25px">40, 60 and 70 describe approximate exposure to company shares. They aren’t scores or expected returns.</div><div class="fund-grid">${FUNDS.map(f=>fundCard(f)).join('')}</div><p class="micro" style="margin-top:25px">Sygnia’s June 2026 cost figures, checked 9 September 2026. Costs can change. The available class and account eligibility must be confirmed before investment.</p>`)}
function feesPage(){shell(title('EVERY COST, IN VIEW','Know what you’re paying.','Our fee is 0.25% a year plus VAT. Fund costs and the provider’s administration charge sit alongside it.')+`<div class="fee-layout"><section class="fee-feature"><p class="eyebrow">MONEY IN MOTION PLATFORM FEE</p><div class="big-fee">0.25<span>% + VAT</span></div><h3>0.2875% including VAT.</h3><p>That’s R287.50 a year on an unchanged R100,000 investment, for our platform fee alone.</p><span class="tag">No adviser fee</span></section><section class="card"><h3>Example: Balanced 70 on R100,000</h3><dl class="fee-lines">${[['Fund expenses (TER)','0.45%'],['Fund transaction costs','0.05%'],['Money in Motion, including VAT','0.2875%'],['Sygnia administration, including VAT','0.4025%'],['Illustrative annual total','1.19%']].map(([t,v],i)=>`<div class="${i===4?'fee-total':''}"><dt>${t}</dt><dd>${v}</dd></div>`).join('')}</dl><p>About <b>R1,190 a year</b> if the balance stays at R100,000.</p><p class="micro">Uses Sygnia’s published retail charge. Our provider agreement isn’t confirmed, so this is an illustration, not a final quote. Taxes and event-based charges aren’t included.</p></section></div>${feeSection(feeState)}<section class="section"><div class="section-head"><h2>Compare annual costs.</h2><p>Examples at R100,000. VAT included where applicable.</p></div><div class="table-scroll"><table><caption class="sr-only">Illustrative annual costs</caption><thead><tr><th>Sygnia fund</th><th>Fund expenses</th><th>Transactions</th><th>Money in Motion</th><th>Provider</th><th>Total</th></tr></thead><tbody>${FUNDS.map(f=>`<tr><th scope="row">${f.name}</th><td>${percent(f.ter)}</td><td>${percent(f.tc)}</td><td>0.2875%</td><td>0.4025%</td><td><b>${percent(totalCost(f))}</b></td></tr>`).join('')}</tbody></table></div></section><div class="section account-grid"><article class="card"><h3>What is a fund cost?</h3><p>Expenses and trading costs are reflected in the fund’s value. They aren’t an extra bill. The total investment charge includes both, so we don’t add the management fee again.</p></article><article class="card"><h3>What can change?</h3><p>Fund costs are historical and updated periodically. Provider fees depend on your account and linked investments. Tax, two-pot transaction fees or policy restrictions may also apply.</p></article></div><p class="micro" style="margin-top:25px">${source('product/sygnia-direct-investment/','Provider fee schedule')} · ${source('fund/sygnia-skeleton-balanced-70-fund/','Balanced 70 costs')}. No negotiated reduction assumed.</p><a href="#calculator" class="button" style="margin-top:25px">See the effect over time →</a>`);bindFeeImpact(app,feeState)}
function calculatorPage(){shell(title('INVESTMENT CALCULATOR','What could regular investing do?','Change the numbers and explore. This is an illustration of assumptions, not a forecast or guaranteed return.')+`<div class="calculator-layout"><form id="calc-form" class="card"><div class="fields">${field('monthly','Monthly contribution (R)','number',calc.monthly,0,1000000)}${field('lump','Initial lump sum amount (R)','number',calc.lump,0,100000000)}${field('inc','Yearly contribution increase (%)','number',calc.inc??0,0,20,.1)}${field('years','Years invested','number',calc.years,1,60)}${field('gross','Growth after fees (% a year)','number',calc.gross,-20,20,.1)}</div><button class="button" type="submit">Update illustration →</button></form><div id="calc-result" class="projection" aria-live="polite"></div></div><p class="notice" style="margin-top:24px">Illustrates a discretionary investment before personal tax. TFSA limits, RA access rules and endowment tax aren’t applied here. Provider terms for Money in Motion still need confirmation.</p>`);document.querySelector('#calc-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));calc={monthly:+d.monthly,lump:+d.lump,years:+d.years,gross:+d.gross,inc:+d.inc,afterFees:true,fund:calc.fund};drawProjection()};drawProjection();app.querySelector('.wrap').insertAdjacentHTML('beforeend',feeSection(feeState));bindFeeImpact(app,feeState)}
function drawProjection(){const p=project(calc);document.querySelector('#calc-result').innerHTML='<p class="eyebrow">ILLUSTRATED VALUE AFTER '+calc.years+' YEARS</p><h2>'+money(p.value)+'</h2><p class="muted">Compared with '+money(p.paid)+' contributed</p>'+growthChart(p,{id:'calculator'})+'<div class="projection-stats"><div><span>Total contributions</span><strong>'+money(p.paid)+'</strong></div></div><p class="micro">Assumes '+calc.gross+'% growth after fees and '+(calc.inc??5)+'% contribution increases each year; monthly payments at the start of each month. The growth rate assumes all fees are already included; we don’t deduct them again. Personal tax and other linked accounts aren’t modelled. Returns are not guaranteed.</p><details><summary>See the year-by-year numbers</summary><div class="table-scroll"><table><thead><tr><th>Year</th><th>Contributions</th><th>Potential growth / loss</th><th>Value</th></tr></thead><tbody>'+p.points.slice(1).map(x=>'<tr><th scope="row">'+x.year+'</th><td>'+money(x.paid)+'</td><td>'+money(x.value-x.paid)+'</td><td>'+money(x.value)+'</td></tr>').join('')+'</tbody></table></div></details>'}
const lessons=[['What is investing?','You put money into assets such as company shares, bonds or cash investments. The aim is to grow it or earn income over time. Your investment can lose value.'],['What is a fund?','A fund pools money from many people into a mix of investments. You own units in the fund. Their value changes as the investments inside it change.'],['What does risk mean?','Risk includes losing money or not reaching your goal. A lower-risk investment can struggle to keep up with rising prices. A higher-risk fund can fall sharply before you need to withdraw.'],['What happens when markets fall?','Your investment may be worth less than you paid. More time may allow it to recover, but recovery isn’t guaranteed. Money for emergencies needs a different plan from long-term investing.'],['What is compound growth?','Returns that stay invested can earn returns of their own. Time and regular contributions help this build up. Losses and fees also compound.'],['Can I take my money out?','It depends on the account. Discretionary withdrawals take time to process. TFSA withdrawals don’t restore contribution room. An RA reserves most money for retirement. An endowment restricts access for five years.'],['What is FICA?','The provider must identify who is investing and where the money comes from. You may need identity, address and bank evidence, tax details and additional checks.'],['Who holds my money?','In the proposed service, investment administration would run through the provider. Money in Motion isn’t connected to Sygnia yet. This preview can’t accept money or live applications.'],['How is my fund chosen?','Your answers create a risk profile. We match that profile to a fund, then show the account options and why they fit your answers. You choose the account and approve the application. This preview model still needs validation before live use.']];
function learnPage(){shell(title('THE BASICS','A little knowledge.<br>A clearer decision.','Short answers to common questions. Open any topic — there’s no need to read everything at once.')+`<div class="learn-layout"><div class="lessons">${lessons.map(([q,a],i)=>`<details ${i===0?'open':''}><summary><span class="lesson-no">${String(i+1).padStart(2,'0')}</span>${q}</summary><div class="detail-body">${a}</div></details>`).join('')}</div><aside class="helper"><p class="eyebrow">PUT IT INTO PRACTICE</p><h3>Start with your own plans.</h3><p>Explore what time, budget and risk mean for you.</p><a href="#profile" class="button light" style="margin-top:25px">Start my profile →</a></aside></div>`)}
function legalPage(){shell(title('ABOUT THIS SERVICE','Clear about what this is.','Money in Motion is a proposed self-directed investment service. This version is for reviewing the experience.')+`<div class="legal-copy"><h3>Preview status</h3><p>No account is opened, no money moves and no application reaches Sygnia. The provider connection, operating entity, licence details, complaints contact and commercial terms are not yet in place.</p><h3>Information and choices</h3><p>This preview automatically matches a fund to your risk profile and ranks account options using your answers. The model needs validation, and the service needs the appropriate regulatory permissions before launch. This is not yet a live personalised advice service.</p><h3>Your information</h3><p>Answers and example details stay in this page’s memory. Refreshing or closing it clears them. Selected files aren’t uploaded. Use fictional details and sample documents, not real identity or bank information. Hosting and font services may process ordinary connection data such as an IP address.</p><h3>Before a live service</h3><p>A live service needs a complete privacy notice, secure storage, access controls, verification, retention rules, complaints handling and provider-approved applications and mandates.</p><h3>Sources and ownership</h3><p>Fund and provider information was checked against Sygnia on 9 September 2026. Fund costs use June 2026 figures. Tax information is based on SARS material. Money in Motion is a separate concept; no partnership, provider approval or Money in Motion FSP authorisation is claimed.</p><p>${source('product/sygnia-direct-investment/','Sygnia information')} · <a href="https://www.sars.gov.za/types-of-tax/personal-income-tax/tax-free-investments/" target="_blank" rel="noopener">SARS TFSA rules ↗</a></p></div>`)}
const applicationTitles=['Review your choice','Your details','Your address & income','Identity & tax','Bank & beneficiary','Review & confirm'];
function input(id,label,type='text',min,max){return field(id,label,type,application[id]??'',min,max)}
function select(id,label,options){return `<label class="field">${label}<select name="${id}" required><option value="">Choose an option</option>${options.map(([v,t])=>`<option value="${v}" ${application[id]===v?'selected':''}>${t}</option>`).join('')}</select></label>`}
function check(id,label){return `<label class="check"><input type="checkbox" name="${id}" required ${application[id]?'checked':''}><span>${label}</span></label>`}
function applicationPage(){if(!hasProfile()||profile(answers).blocked||!account||(!fund&&account!=='endowment')){shell(title('APPLICATION PREVIEW','Start with your choices.','Complete your profile and choose one of your account matches. The fund is matched for you.')+'<a class="button" href="#result">Review my options →</a>');return}const match=matchInvestments(answers).options.find(x=>x.account.id===account);if(!match){go('result');return}fund=match.fund?.id||'';const a=match.account,f=match.fund;let body='';
 if(applyStep===0)body=`<div class="selection-summary"><span class="tag">${a.name}</span><h3>${f?f.name:'Endowment fund selection pending'}</h3><p>${money(+answers.monthly)} a month · ${money(+answers.lump)} initial lump sum</p><p class="micro">Your plan uses ${Number(answers.contributionIncrease||0)}% yearly contribution increases. These are illustrative; provider instructions must be agreed before any debit order is set up.</p>${f?`<dl class="fee-lines"><div><dt>Fund total investment charge</dt><dd>${percent(fundCost(f))}</dd></div><div><dt>Money in Motion incl. VAT</dt><dd>0.2875%</dd></div><div><dt>Provider retail charge, first R2m</dt><dd>0.4025%</dd></div><div class="fee-total"><dt>Illustrative annual total at R100,000</dt><dd>${percent(totalCost(f))}</dd></div></dl>`:'<p class="notice warning">Fund eligibility and a complete endowment quote require provider confirmation.</p>'}<p class="micro">Final provider agreement and product eligibility are unconfirmed. <a href="#fees">Full cost explanation</a></p></div><p class="notice">${a.access}</p>${account==='tfsa'?`<h3 style="margin-top:25px">Check your tax-free allowance</h3><p class="muted">Include contributions at every provider. Don’t subtract withdrawals.</p><div class="fields">${input('annual','Already contributed this tax year (R)','number',0,100000000)}${input('lifetime','Contributed over your lifetime, including this year (R)','number',0,100000000)}${field('months','Planned monthly payments before the tax year ends','number',application.months??(new Date().getMonth()>=2?14-new Date().getMonth():2-new Date().getMonth()),0,12)}</div>`:''}${check('choice','I understand the access rules, the possibility of losses and that the costs shown are illustrative.')}`;
 if(applyStep===1)body=`<p class="notice">Use fictional details to try the form. This preview isn’t accepting applications.</p><button class="text-button" type="button" id="example">Fill with example details</button><div class="fields">${input('first','First name')}${input('last','Surname')}${input('email','Email address','email')}${input('phone','Mobile number','tel')}${input('dob','Date of birth','date')}${select('residency','Who is applying?',[['sa','South African adult investing for myself'],['foreign','Adult living in SA with a foreign passport'],['guardian','Parent / guardian'],['other','Another person or a legal entity']])}</div>${check('privacy','I understand that this preview keeps example details in page memory only. No details are sent to Sygnia.')}`;
 if(applyStep===2)body=`<div class="fields">${input('street','Street address')}${input('city','Town or city')}${input('postal','Postal code')}${select('province','Province',['Eastern Cape','Free State','Gauteng','KwaZulu-Natal','Limpopo','Mpumalanga','North West','Northern Cape','Western Cape'].map(x=>[x,x]))}${input('occupation','Occupation or employment status')}${select('source','Where is the investment money coming from?',[['salary','Salary / earnings'],['savings','Savings'],['inheritance','Inheritance'],['sale','Sale of an asset'],['other','Another source']])}${input('sourceDetail','Briefly describe the source of this money')}</div><p class="notice">The provider may ask for evidence of the source of your money. Transfers from another investment need a separate transfer process.</p>`;
 if(applyStep===3)body=`<div class="fields">${select('identityType','Identity document',[['sa','South African identity document'],['passport','Foreign passport']])}${input('identityRef','Example identity reference')}${input('taxCountry','Country where you are tax resident')}${input('taxRef','Example tax reference or reason you have none')}${select('usTax','Are you also a US citizen or US tax resident?',[['no','No'],['yes','Yes'],['unsure','I’m not sure']])}${select('prominent','Do you or a close associate hold a prominent public role?',[['no','No'],['yes','Yes'],['unsure','I’m not sure']])}</div><details><summary>What does a prominent public role mean?</summary><div class="detail-body">For example, a senior government, judicial, military or state-owned company role. Family members and close associates can also require additional checks. The provider determines the full classification.</div></details><h3 style="margin-top:25px">Try the document step</h3><p class="muted">Sample files only. PDF, JPG or PNG, up to 5 MB each. Files are selected locally and never uploaded.</p><div class="uploads">${[['id','Identity document'],['address','Proof of address (normally within 3 months)'],['bank','Proof of bank details (normally within 3 months)']].map(([id,label])=>`<label class="upload">${label}<input type="file" data-doc="${id}" accept="application/pdf,image/jpeg,image/png"><span id="doc-${id}" class="micro">${documents[id]?esc(documents[id].name):'No sample file selected'}</span></label>`).join('')}</div>`;
 if(applyStep===4)body=`<p class="notice">The live provider would verify ownership of your bank account. This preview cannot verify it or create a debit order.</p><div class="fields">${input('holder','Example account-holder name')}${input('bankName','Bank name')}${input('bankNumber','Example account number')}${input('branch','Branch code')}${select('bankType','Account type',[['cheque','Current / cheque'],['savings','Savings']])}${select('debitDay','Preferred monthly debit-order day',[['1','1st'],['7','7th'],['15','15th'],['25','25th']])}</div>${account==='ra'||account==='endowment'?`<h3>Example beneficiary</h3><p class="muted">A person you nominate to receive benefits if you die. RA trustees consider dependants and the law; a nomination doesn’t guarantee payment.</p><div class="fields">${input('beneficiary','Beneficiary full name')}${input('relationship','Relationship')}${input('beneficiaryShare','Share of benefit (%)','number',100,100)}</div>`:''}${check('bankOwn','For this walkthrough, the sample bank details represent an account held in the applicant’s own name.')}`;
 if(applyStep===5)body=`<div class="selection-summary"><p class="eyebrow">CHECK YOUR EXAMPLE APPLICATION</p><h3>${a.name}</h3><p>${f?f.name:'Fund and quote still to be confirmed'}</p><dl class="fee-lines"><div><dt>Applicant</dt><dd>${esc(application.first)} ${esc(application.last)}</dd></div><div><dt>Contribution</dt><dd>${money(+answers.monthly)} monthly</dd></div><div><dt>Starting amount</dt><dd>${money(+answers.lump)}</dd></div><div><dt>Sample documents selected</dt><dd>${Object.keys(documents).length} of 3</dd></div></dl></div>${application.usTax!=='no'||application.prominent!=='no'?'<p class="notice warning">These declarations would require additional provider checks before a real application could proceed.</p>':''}<p class="notice">This confirms the walkthrough only. It is not a signed investment application, debit-order mandate or instruction to invest.</p>${input('signature','Type your full name to confirm this preview')}${check('accuracy','I’ve reviewed the example details and understand the account restrictions and investment risks.')}${check('preview','I understand that no application will be submitted and no account will be opened.')}`;
 shell(`<div class="flow"><div class="flow-top"><a href="#result">← My options</a><span>APPLICATION PREVIEW · ${applyStep+1} OF 6</span></div><div class="progress" role="progressbar" aria-label="Application progress" aria-valuemin="0" aria-valuemax="6" aria-valuenow="${applyStep+1}"><span style="width:${(applyStep+1)/6*100}%"></span></div><div class="flow-layout"><section class="question"><p class="eyebrow">ONE STEP AT A TIME</p><h1>${applicationTitles[applyStep]}</h1><form id="application-form">${body}<p class="error" id="application-error" role="alert"></p><div class="flow-actions"><button class="text-button" id="application-back" type="button">← Back</button><button class="button" type="submit">${applyStep===5?'Complete preview':'Continue'} →</button></div></form></section><aside class="helper application-steps"><p class="eyebrow">YOUR APPLICATION</p>${applicationTitles.map((t,i)=>`<p class="${i===applyStep?'current':''}"><span>${i<applyStep?'✓':i+1}</span>${t}</p>`).join('')}<div class="helper-bottom">Preview only.<br>Use fictional details.</div></aside></div></div>`);
 document.querySelector('#application-back').onclick=()=>{if(applyStep){applyStep--;applicationPage()}else go('result')};
 document.querySelector('#example')?.addEventListener('click',()=>{Object.assign(application,{first:'Sam',last:'Example',email:'sam@example.com',phone:'0000000000',dob:'1990-01-01',residency:'sa',street:'1 Example Street',city:'Johannesburg',postal:'2000',province:'Gauteng',occupation:'Employed',source:'salary',sourceDetail:'Example salary savings',identityType:'sa',identityRef:'DEMO-ID-NOT-REAL',taxCountry:'South Africa',taxRef:'DEMO-TAX-NOT-REAL',usTax:'no',prominent:'no',holder:'Sam Example',bankName:'Example Bank',bankNumber:'0000000000',branch:'000000',bankType:'cheque',debitDay:'1',beneficiary:'Alex Example',relationship:'Partner',beneficiaryShare:'100',signature:'Sam Example'});applicationPage()});
 app.querySelectorAll('[data-doc]').forEach(el=>el.onchange=()=>{const f=el.files[0],id=el.dataset.doc;delete documents[id];if(f&&(!['application/pdf','image/jpeg','image/png'].includes(f.type)||f.size>5*1024*1024||f.size===0)){el.value='';document.querySelector('#doc-'+id).textContent='Choose a non-empty PDF, JPG or PNG of 5 MB or less.';return}if(f)documents[id]=f;document.querySelector('#doc-'+id).textContent=f?f.name:'No sample file selected'});
 document.querySelector('#application-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));let error='';
 if(applyStep===0&&account!=='endowment'&&!(+answers.monthly>=500||+answers.lump>=10000))error='This preview uses a minimum of R500 a month or R10,000 once-off. Return to your profile to adjust the amount. Exact product minimums still need confirmation.';
 if(applyStep===0&&account==='tfsa'){const t=tfsaCheck({annual:+d.annual,lifetime:+d.lifetime,lump:+answers.lump,monthly:+answers.monthly,months:+d.months});if(!t.ok)error=t.reason;else if(+answers.monthly*12>46000)error='A full year of these monthly payments would exceed the R46,000 annual TFSA allowance. Lower the amount or compare a discretionary account.'}
 if(applyStep===1){if(!/^\+?[\d ()-]{9,16}$/.test(d.phone))error='Enter a valid-format example mobile number.';if(new Date(d.dob)>=new Date()||new Date(d.dob)<new Date('1900-01-01'))error='Check the example date of birth.';const age=(Date.now()-new Date(d.dob).getTime())/(365.2425*86400000);if(age<18||['guardian','other'].includes(d.residency))error='This application walkthrough currently covers adults investing for themselves. A guardian or entity application needs the provider’s separate process.'}
 if(applyStep===2&&!/^\d{4}$/.test(d.postal))error='Enter a four-digit South African postal code.';
 if(applyStep===3&&Object.keys(documents).length!==3)error='Select all three sample documents. They won’t be uploaded.';
 if(applyStep===4&&(!/^\d{6,16}$/.test(d.bankNumber)||!/^\d{6}$/.test(d.branch)))error='Use a 6–16 digit example account number and a 6-digit branch code.';
 if(applyStep===5&&d.signature.trim().toLowerCase()!==`${application.first} ${application.last}`.trim().toLowerCase())error='Type the full name entered in the example application.';
 if(error){document.querySelector('#application-error').textContent=error;return}Object.assign(application,d);if(applyStep<5){applyStep++;applicationPage();window.scrollTo(0,0)}else{completed=true;go('complete')}};
}
function completePage(){if(!completed){go('apply');return}shell(`<div class="completion"><span class="completion-check">✓</span><p class="eyebrow">WALKTHROUGH COMPLETE</p><h1>You’ve reached the end<br>of the preview.</h1><p class="lead">No application was submitted. No account was opened. You’ve tried the journey from your first question to the final review.</p><div class="notice">Live investing will become possible only after the provider connection, secure onboarding and required licence details are in place.</div><div class="actions"><button class="button" id="download">Download my choice summary ↓</button><button class="button secondary" id="clear">Clear example details</button></div><p class="micro">The download includes your account, fund and contribution choices. It excludes identity, bank and document details.</p></div>`);document.querySelector('#clear').onclick=()=>{application={};documents={};answers={};completed=false;account='';fund='';step=0;go('home')};document.querySelector('#download').onclick=()=>{const a=ACCOUNTS.find(x=>x.id===account),f=FUNDS.find(x=>x.id===fund),content=`MONEY IN MOTION — PREVIEW CHOICE SUMMARY\nNot an application or investment instruction.\n\nAccount: ${a.name}\nFund: ${f?f.full:'Endowment fund pending provider confirmation'}\nMonthly: ${money(+answers.monthly)}\nOnce-off: ${money(+answers.lump)}\n${f?'Illustrative annual cost at R100,000: '+percent(totalCost(f))+'\n':''}Money in Motion fee: 0.25% plus VAT (0.2875% inclusive)\nFund costs and provider administration are additional.\nFinal provider agreement and eligibility are not confirmed.\n\nAccess: ${a.access}\nTrade-off: ${a.bad}\n\nNo account has been opened. No details were submitted.\n`;const url=URL.createObjectURL(new Blob([content],{type:'text/plain'})),link=document.createElement('a');link.href=url;link.download='Money in Motion-preview-summary.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}}
function render(){const route=location.hash.slice(1)||'home';document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.hash==='#'+route);if(a.hash==='#'+route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});({home,'how-it-works':home,profile:profilePage,result:resultPage,accounts:accountsPage,funds:fundsPage,fees:feesPage,calculator:calculatorPage,learn:learnPage,legal:legalPage,apply:applicationPage,complete:completePage}[route]||home)();document.title=`${({profile:'Your profile',result:'Your options',accounts:'Accounts',funds:'Sygnia funds',fees:'Costs',calculator:'Calculator',learn:'Learn',apply:'Application preview',complete:'Preview complete',legal:'About & privacy'})[route]||'Your money. Moving forward.'} — Money in Motion`;if(route==='how-it-works')document.querySelector('#how-it-works')?.scrollIntoView();else window.scrollTo(0,0)}
document.querySelector('header > .button').onclick=e=>{e.preventDefault();startJourney()};
window.addEventListener('hashchange',render);render();
if(document.modelContext?.registerTool){const lifetime=new AbortController();window.addEventListener('pagehide',()=>lifetime.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'configure_investment_illustration',title:'Explore an investment illustration',description:'Configure the visible discretionary investment calculator. Does not select or submit an investment.',inputSchema:{type:'object',properties:{monthly:{type:'number',minimum:0,maximum:1000000},years:{type:'integer',minimum:1,maximum:60}},required:['monthly','years'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!Number.isFinite(input.monthly)||input.monthly<0||input.monthly>1000000||!Number.isInteger(input.years)||input.years<1||input.years>60||Object.keys(input).some(k=>!['monthly','years'].includes(k)))throw new Error('Enter a valid monthly amount and 1–60 whole years.');calc={...calc,monthly:input.monthly,years:input.years};history.replaceState(null,'','#calculator');render();const p=project(calc);return {monthly:calc.monthly,years:calc.years,illustratedValue:p.value,notAForecast:true}}},{signal:lifetime.signal})).catch(()=>{});}catch{}}
